// Get today's date in IST as YYYY-MM-DD
const now = new Date();
const ist = new Date(now.getTime() + (5.5 * 60 * 60 * 1000));
const today = ist.toISOString().split('T')[0];

const project_root = '/Users/sahudilip/Desktop/Product Dev/DPDPA Daily Brief';
const python_path = '/usr/bin/python3'; // Update if using venv

return [{
  json: {
    today_date: today,
    project_root: project_root,
    python: python_path
  }
}];

const stdout = $input.first().json.stdout || '';
let roadmap;
try {
  // Find the JSON object in stdout (last JSON line wins)
  const lines = stdout.trim().split('\n');
  for (let i = lines.length - 1; i >= 0; i--) {
    try {
      roadmap = JSON.parse(lines[i]);
      break;
    } catch(e) { continue; }
  }
} catch(e) {
  throw new Error('Failed to parse roadmap output: ' + stdout.slice(0, 300));
}

if (!roadmap) throw new Error('No JSON found in roadmap output: ' + stdout.slice(0, 300));

return [{ json: roadmap }];

// Extract date from stdout for downstream nodes
const stdout = $input.first().json.stdout || '';
let content;
try {
  const lines = stdout.trim().split('\n');
  for (let i = lines.length - 1; i >= 0; i--) {
    try { content = JSON.parse(lines[i]); break; } catch(e) { continue; }
  }
} catch(e) {}

const date = content?.date || new Date().toISOString().split('T')[0];

return [{ json: { date, stdout } }];

